            dw    PAL_TITLE_MATCH
            dw    PAL_TITLE_2_MATCH
            dw    PAL_LEVEL_1_MATCH
            dw    PAL_LEVEL_2_MATCH
            dw    PAL_LEVEL_3_MATCH
