            db    $37,$12,$0F,$36,$16,$0F,$20,$26,$16,$20,$1B,$0F   ; SP0-SP3
PAL_LEVEL_5_MATCH
            db    $20,$10,$1C,$20,$10,$0A,$16,$30,$10,$20,$22,$02   ; BG0-BG3
            db    $37,$12,$0F,$36,$16,$0F,$20,$26,$16,$20,$00,$0F   ; SP0-SP3
PAL_LEVEL_6_MATCH
