            db    $37,$12,$0F,$36,$16,$0F,$20,$26,$16,$20,$00,$0F   ; SP0-SP3
PAL_LEVEL_8_MATCH
            db    $10,$00,$07,$36,$15,$06,$35,$15,$04,$18,$13,$03   ; BG0-BG3
